"""Plot actual saved evaluation and controlled experiment outputs."""
import json
from pathlib import Path
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import FancyArrowPatch, Rectangle
OUT=Path(__file__).resolve().parent
PKG=OUT.parent
M=json.loads((PKG.parent/'models/metrics.json').read_text())
D=pd.read_csv(OUT/'experiment_results.csv')
FIG=PKG/'01_Project_Report/Figures'
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False})
def save(fig,name):
 fig.savefig(FIG/f'{name}.png',dpi=180,bbox_inches='tight',facecolor='white')
 fig.savefig(OUT/'Experiment_Charts'/f'{name}.svg',bbox_inches='tight',facecolor='white')
 plt.close(fig)
fig,ax=plt.subplots(figsize=(5.5,4))
ax.imshow(M['confusion_matrix'],cmap='Blues',vmin=0,vmax=20)
for i in range(2):
 for j in range(2):ax.text(j,i,str(M['confusion_matrix'][i][j]),ha='center',va='center',fontsize=22,color='#10243e')
ax.set(xticks=[0,1],yticks=[0,1],xticklabels=['Human-style','AI-style'],yticklabels=['Human-style','AI-style'],xlabel='Predicted label',ylabel='Actual label',title='Selected model • synthetic held-out test (n=32)')
save(fig,'Confusion_Matrix')
f=M['feature_importance'][:8]
fig,ax=plt.subplots(figsize=(6.5,4))
ax.barh([x['feature'].replace('structure: ','') for x in f][::-1],[x['importance'] for x in f][::-1],color='#4068bc')
ax.set(xlabel='Absolute coefficient (not signed attribution)',title='Selected Logistic Regression • global signals')
save(fig,'Feature_Importance')
fig,ax=plt.subplots(figsize=(6.5,4))
ax.barh(D.iloc[:6].experiment[::-1],D.iloc[:6].ai_probability[::-1],color='#4068bc')
ax.axvline(.5,color='#b56f2d',ls='--');ax.set(xlim=(0,1.1),xlabel='Saved-model AI probability',title='Actual input sensitivity • synthetic-trained model')
for i,p in enumerate(D.iloc[:6].ai_probability[::-1]):ax.text(p+.015,i,f'{p:.4f}',va='center',fontsize=9)
save(fig,'Input_Sensitivity')
fig,ax=plt.subplots(figsize=(10,3.2));ax.axis('off');ax.set_xlim(0,10);ax.set_ylim(0,3.2)
items=[('React input',.05),('FastAPI\nvalidation',2.1),('Static\nfeatures',4.15),('Saved ML\npipeline',6.2),('Result\ndisplay',8.25)]
for t,x in items:
 ax.add_patch(Rectangle((x,1.5),1.65,.85,facecolor='#eef3fb',edgecolor='#4068bc',linewidth=1.2));ax.text(x+.825,1.925,t,ha='center',va='center',fontsize=10)
 if x<8:ax.add_patch(FancyArrowPatch((x+1.65,1.925),(x+2.0,1.925),arrowstyle='->',mutation_scale=14,color='#4068bc'))
ax.text(5,.65,'Offline: CSV → grouped split → fitted TF-IDF/scaler/classifiers → saved pipeline + real metrics',ha='center',fontsize=10)
ax.text(5,2.8,'Python is user-selected; submitted source never executes',ha='center',fontsize=11)
save(fig,'Architecture')
compare=[]
base=D.iloc[0]
for _,r in D.iloc[1:6].iterrows():
 a=json.loads(base.features);b=json.loads(r.features)
 compare.append({'experiment':r.experiment,'original_input':base.configuration,'modified_input':r.configuration,'changed_features':json.dumps({k:[a[k],b[k]] for k in a if a[k]!=b[k]}),'original_prediction':base.prediction,'modified_prediction':r.prediction,'original_ai_probability':base.ai_probability,'modified_ai_probability':r.ai_probability,'interpretation':'Unlabeled different task; cannot estimate accuracy.' if r.experiment=='unseen problem' else 'Controlled source change; class need not change. Multiple correlated features can change together.'})
pd.DataFrame(compare).to_csv(OUT/'paired_input_comparisons.csv',index=False)
report='''# Live Experiments and Demonstrations

Run `python evaluation_package/05_Experiments/run_experiments.py` then `python evaluation_package/05_Experiments/make_charts.py` from the project root. Install optional plotting dependencies with `python -m pip install -r evaluation_package/05_Experiments/requirements.txt`.

The runner loads the saved model for input edits and independently fits experimental Logistic Regression configurations. It does not overwrite the deployed model. Configuration metrics use the existing validation partition, not repeated test-set tuning. All output scores below were generated by the runner; percentages must not be interpreted as real-world reliability.

## Experiments 1–4 and 8: paired source changes

Original/modified inputs, changed numeric features, class predictions and probabilities are stored in paired_input_comparisons.csv. Every feature dictionary is also present in experiment_results.csv. For finite integer lists, renaming, adding comments, compacting spaces and replacing the explicit filtering loop by a comprehension preserve the baseline behavior. The factorial probe is a different unlabeled task; it tests whether inference runs, not whether authorship is correctly identified.

| Experiment | Original class / AI score | Modified class / AI score | Interpretation |
|---|---|---|---|
'''
for row in compare:report+=f"| {row['experiment']} | {row['original_prediction']} / {row['original_ai_probability']:.4f} | {row['modified_prediction']} / {row['modified_ai_probability']:.4f} | {row['interpretation']} |\n"
report+='\n## Experiments 5–7: configuration, ablation and threshold\n\nNumeric style group: comment ratio, average line length, average identifier length, snake/camel ratios and blank-line ratio. Structural group: function, loop, conditional, class, exception, AST-node, nesting and docstring counts. Remaining size/token features are retained; these ablations are not a disjoint decomposition of every possible style signal.\n\n| Configuration | Baseline AI score | Validation accuracy | Precision | Recall | F1 | ROC AUC |\n|---|---:|---:|---:|---:|---:|---:|\n'
for _,r in D.iloc[6:].iterrows():report+=f'| {r.configuration} | {r.ai_probability:.6f} | {r.accuracy:.4f} | {r.precision:.4f} | {r.recall:.4f} | {r.f1:.4f} | {r.roc_auc:.4f} |\n'
report+='\nC=1 with all features is the reference configuration. Smaller C gives stronger regularization and changes probability despite unchanged validation classes. All ablations have perfect validation metrics on this artificial fixture, so they cannot establish which groups are most useful on real data. Thresholds 0.4–0.7 leave validation precision and recall unchanged because no scores cross those cutoffs. For the recorded structural-refactor probe, its probability near 0.5442 would predict AI at 0.5 and human at 0.6 without refitting; the class rule changes while the score stays fixed. This is a threshold illustration on one fixed score, not a newly measured validation result.\n\n## Practical demonstration sequence\n\n1. Start the local backend and frontend using the repository README.\n2. Paste the baseline from paired_input_comparisons.csv and record its estimate.\n3. Paste each paired modification and inspect the returned raw features and score.\n4. Open the generated CSV for C, ablation and validation-threshold comparisons.\n5. Explain any unchanged class as a legitimate outcome. Do not edit the UI prediction or search until a desired result appears.\n6. Show the factorial score and explicitly say its origin is unlabeled.\n\nReproduce experiments after every feature or model change; report schema-2 values, not the older schema-1 probabilities.\n'
(OUT/'Live_Experiments_and_Demonstrations.md').write_text(report,encoding='utf-8')
